          "speaker": "🧪 Kỹ Sư Vật Liệu EPS",
          "q_zh": "低温路缘石砧测试内胆开裂，发泡密度如何调整？",
          "q_pinyin": "dī wēn lù yuán shí zhēn cè shì nèi dǎn kāi liè， fā pào mì dù rú hé tiáo zhěng？",
