          "q_audio": "audio/dlg_29_q.mp3",
          "q_audio_en": "audio/dlg_29_q_en.mp3",
          "correct_zh": "核查熟化时间与蒸汽压力，提升粒子熔结度与韧性。",
          "correct_pinyin": "hé chá shú huà shí jiān yǔ zhēng qì yā lì， tí shēng lì zi róng jié dù yǔ rèn xìng。",
          "correct_en": "Verify bead aging and steam fusion pressure to boost EPS toughness.",
