          "speaker": "👷‍♀️ Chủ Quản Chuyền Lắp Ráp",
          "q_zh": "装配 MIPS 低摩擦层时，品检员重点确认哪一项？",
          "q_pinyin": "zhuāng pèi  MIPS  dī mó cā céng shí， pǐn jiǎn yuán zhòng diǎn què rèn nǎ yī xiàng？",
          "q_en": "When assembling the MIPS low-friction layer, what must QC verify most closely?",
