          "speaker": "🧑‍🔬 Kỹ Thuật Viên Phòng Lab",
          "q_zh": "按国标 GB 24429 测试前，样品必须完成哪些预处理？",
          "q_pinyin": "àn guó biāo  GB 24429  cè shì qián， yàng pǐn bì xū wán chéng nǎ xiē yù chǔ lǐ？",
