          "speaker": "🤖 Kỹ Sư Tự Động Hóa Ép Phun",
          "q_zh": "注塑机机械手报警吸盘真空不足，开机前怎么安全复位？",
          "q_pinyin": "zhù sù jī jī xiè shǒu bào jǐng xī pán zhēn kōng bù zú， kāi jī qián zěn me ān quán fù wèi？",
          "q_en": "The molding robot alarmed low suction vacuum; how do we reset safely before restart?",
          "q_vi": "Cánh tay robot máy ép báo động thiếu áp hút chân không, trước khi chạy lại reset an toàn thế nào?",
          "q_audio": "audio/dlg_32_q.mp3",
          "q_audio_en": "audio/dlg_32_q_en.mp3",
