          "speaker": "🏷️ Chủ Quản Tổ Tem Nước",
          "q_zh": "水标贴花过 UV 固化炉后起泡且偏位，标准怎么管控？",
          "q_pinyin": "shuǐ biāo tiē huā guò  UV  gù huà lú hòu qǐ pào qiě piān wèi， biāo zhǔn zěn me guǎn kòng？",
          "q_en": "Water-slide decals blistered and shifted after the UV curing oven; how do we enforce spec?",
          "q_vi": "Tem nước qua lò sấy UV bị phồng bọt khí và lệch vị trí, tiêu chuẩn kiểm soát thế nào?",
          "q_audio": "audio/dlg_44_q.mp3",
          "q_audio_en": "audio/dlg_44_q_en.mp3",
          "correct_zh": "定位治具控制对位误差一毫米内，刮净水汽并充分烘烤除水后再喷UV。",
          "correct_pinyin": "dìng wèi zhì jù kòng zhì duì wèi wù chā yī háo mǐ nèi， guā jìng shuǐ qì bìng chōng fèn hōng kǎo chú shuǐ hòu zài pēn UV。",
          "correct_en": "Lock alignment <=1.0mm with jigs, squeegee all bubbles, and fully bake moisture before UV coat.",
          "correct_vi": "Dùng gá khóa độ lệch ≤1.0mm, vuốt sạch bọt nước và sấy khô kiệt ẩm trước khi phủ UV.",
          "wrong_zh": "水标刚沾水贴上不用刮平，直接带水进高能 UV 炉暴晒。",
          "wrong_pinyin": "shuǐ biāo gāng zhān shuǐ tiē shàng bù yòng guā píng， zhí jiē dài shuǐ jìn gāo néng  UV  lú pù shài。",
          "wrong_en": "Skip squeegeeing and send wet decals straight into the high-power UV oven.",
          "wrong_vi": "Tem vừa nhúng nước dán lên khỏi cần vuốt, đưa thẳng còn ướt vào lò UV chiếu mạnh.",
