          "q_en": "How do we guarantee zero missing manuals per box and 100% lot traceability?",
          "q_vi": "Làm sao đảm bảo mỗi hộp mũ xuất đi không sót sách hướng dẫn và truy xuất được 100% mã lô?",
          "q_audio": "audio/dlg_49_q.mp3",
          "q_audio_en": "audio/dlg_49_q_en.mp3",
          "correct_zh": "逐顶扫描内侧二维码绑定工单，并经自动检重秤拦截克重异常彩盒。",
          "correct_pinyin": "zhú dǐng sǎo miáo nèi cè èr wéi mǎ bǎng dìng gōng dān， bìng jīng zì dòng jiǎn zhòng chèng lán jié kè zhòng yì cháng cǎi hé。",
          "correct_en": "Scan each helmet's inner QR code to bind work orders, and use inline checkweighers to reject underweight boxes.",
