          "wrong_en": "Rely on worker memory at month-end; customers won't notice missing manuals.",
          "wrong_vi": "Cuối tháng dựa vào trí nhớ công nhân ghi sổ tay, thiếu vài cuốn hướng dẫn khách không biết đâu.",
