          "a_audio_en": "audio/dlg_49_a_en.mp3",
          "feynman_hook": "Kết hợp Quét mã QR (二维码追溯) + Cân tự động (自动检重秤 ±5g) khóa cứng cả dữ liệu số lẫn linh kiện vật lý 100%!"
