          "correct_pinyin": "què rèn qī diǎn jiǎn wú lòu guāng shuǐ zì、 guà zú fáng cháo gān zào jì、 lā jǐn fáng hù wǎng bìng pāi zhào hé duì qiān fēng hào。",
          "correct_en": "Verify 7-point leak/moisture check, hang desiccants, secure cargo net, and photograph the bolt seal number.",
          "correct_vi": "Xác nhận kiểm 7 điểm không thủng dột, treo đủ dây hút ẩm, căng lưới chắn cửa và chụp ảnh đối chiếu số chì.",
          "wrong_zh": "下雨天直接露天敞门装湿纸箱，不用挂干燥剂也不用锁铅封。",
          "wrong_pinyin": "xià yǔ tiān zhí jiē lù tiān chǎng mén zhuāng shī zhǐ xiāng， bù yòng guà gān zào jì yě bù yòng suǒ qiān fēng。",
          "wrong_en": "Load wet cartons outdoors in the rain with zero desiccants and no container bolt seal.",
          "wrong_vi": "Trời mưa cứ mở cửa đóng thùng ướt ngoài bãi, khỏi cần treo hút ẩm hay bấm kẹp chì.",
          "a_audio": "audio/dlg_51_a.mp3",
          "a_audio_en": "audio/dlg_51_a_en.mp3",
